#include <stdint.h>

#if !defined(__SOFT_FP__) && defined(__ARM_FP)
  #warning "FPU is not initialized, but the project is compiling for an FPU. Please initialize the FPU before use."
#endif

int main(void)
{
	uint32_t *ptrClkCntrlReg = (uint32_t*)0x40023830;
	uint32_t *ptrPortDModeReg = (uint32_t*)0x40020C00;
	uint32_t *ptrPortDOutReg = (uint32_t*)0x40020C14;

	uint32_t *ptrPortAModeReg = (uint32_t*)0x40020000;
	uint32_t *ptrPortAInReg = (uint32_t*)0x40020010;


	// Enable clock for GPIOD and GPIOA pheripheral in AHB1NER
	*ptrClkCntrlReg |= (1<<3); // GPIOD

	*ptrClkCntrlReg |= (1<<0); // GPIOA

	//Configure the mode of GPIOD IO pin as output
	*ptrPortDModeReg &= ~( 3 << 24); //Clear 24th and 25th bit
	*ptrPortDModeReg |= (1 << 24); //Set 24th bit

	//Configure the mode of GPIOA IO pin as Input mode
	*ptrPortAModeReg &= ~(3 << 0);

	while(1){
		// Read pin status (bit 0 of the PA0)
		uint8_t status = (uint8_t)(*ptrPortAInReg & 0x1);
		if(status){
			//Set 12th bit to high
			*ptrPortDOutReg |= (1<<12);
		}
		else{
			//Set 12th bit to high
			*ptrPortDOutReg &= ~(1<<12);
		}
	}
}
